"""Check Bates-numbered document ranges from a manifest CSV for gaps/overlaps/errors."""

import csv
import re
import sys
from dataclasses import dataclass


@dataclass(frozen=True)
class Range:
    doc_id: str
    first: tuple  # (prefix, number)
    last: tuple

    @property
    def start(self):
        return self.first[1]

    @property
    def end(self):
        return self.last[1]


def parse_bates(value):
    """Split 'ACME-000123' into ('ACME-', 123). Raises ValueError on bad format."""
    m = re.fullmatch(r"([A-Za-z]+-?)(\d+)", value.strip())
    if not m:
        raise ValueError(f"invalid bates number: {value!r}")
    return (m.group(1), int(m.group(2)))


def load_ranges(csv_text):
    """Parse manifest CSV text (with header) into a list of Range objects."""
    reader = csv.DictReader(csv_text.splitlines())
    ranges = []
    for row in reader:
        first = parse_bates(row["first_bates"])
        last = parse_bates(row["last_bates"])
        if first[0] != last[0]:
            raise ValueError(f"{row['doc_id']}: mismatched prefixes")
        ranges.append(Range(row["doc_id"], first, last))
    ranges.sort(key=lambda r: r.start)
    return ranges


def check(ranges):
    """Return report lines for gaps, overlaps, and inverted rows."""
    problems = []
    prev = None
    for r in ranges:
        if r.end < r.start:
            problems.append(f"REVERSED {r.doc_id}: last < first ({r.last[0]}{r.end:06d} < {r.first[0]}{r.start:06d})")
        if prev is not None:
            if r.start > prev.end + 1:
                gap = r.start - prev.end - 1
                problems.append(
                    f"GAP after {prev.doc_id} -> {r.doc_id}: "
                    f"{prev.end + 1}..{r.start - 1} ({gap} missing)"
                )
            elif r.start <= prev.end:
                problems.append(
                    f"OVERLAP {prev.doc_id} ({prev.end}) and {r.doc_id} ({r.start})"
                )
        prev = r
    return problems


def report(csv_text, out=sys.stdout):
    """Print the audit report for manifest CSV text."""
    ranges = load_ranges(csv_text)
    problems = check(ranges)
    if problems:
        out.write("\n".join(problems) + "\n")
    else:
        out.write("OK\n")
    return problems


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1:
        print("usage: bates_gaps.py MANIFEST.csv", file=sys.stderr)
        return 2
    with open(args[0], newline="") as f:
        problems = report(f.read())
    return 0 if not problems else 1


if __name__ == "__main__":
    sys.exit(main())

